const PLUGIN_DESCRIPTION = "analyzr command line, bundled with the analyzr-integrate plugin (no seed, no mcp; run it as node <path of analyzr.mjs> <command>, as its next steps name it): import, list, requeue, delete, amend and pull models, list, export, answer and act on open questions, list, export and withdraw model amendments, push and pull the value chain, manage agent tokens and auto-accept rules";
function nodeCommand(script) {
	return `node ${shellArg(script)}`;
}
function pluginCommand(script, url) {
	return `${nodeCommand(script)} --url ${shellArg(url)}`;
}
function buildPluginProgram(io, script) {
	return buildCoreProgram(io, {
		description: PLUGIN_DESCRIPTION,
		commandName: (url) => pluginCommand(script, url),
		mcpEntry: null,
		ownerKeyLoopbackOnly: true
	});
}
async function runProgram(argv, io, build) {
	const program = build(io);
	guardValues(program);
	try {
		await program.parseAsync(argv, { from: "user" });
		return 0;
	} catch (err) {
		if (err instanceof CommanderError) return err.exitCode;
		if (err instanceof CliError) {
			io.stderr(`analyzr: ${err.message}\n`);
			return err.exitCode;
		}
		io.stderr(`analyzr: ${err instanceof Error ? err.message : String(err)}\n`);
		return 1;
	}
}
